import{_ as e,o as t,c as r,a2 as s}from"./chunks/framework.Cmuzzkcw.js";const u=JSON.parse('{"title":"CLI reference","description":"","frontmatter":{},"headers":[],"relativePath":"tooling/cli.md","filePath":"tooling/cli.md"}'),n={name:"tooling/cli.md"};function d(a,o,c,g,i,l){return t(),r("div",null,[...o[0]||(o[0]=[s('<h1 id="cli-reference" tabindex="-1">CLI reference <a class="header-anchor" href="#cli-reference" aria-label="Permalink to &quot;CLI reference&quot;">​</a></h1><p>The <strong><code>bjs</code></strong> CLI (package <strong><code>@banana-universe/bananajs-cli</code></strong>) is a <strong>first-class product surface</strong>: scaffolding, codegen, static analysis, DB/OpenAPI tooling, and <strong>AI</strong> flows—including <strong><code>.bananarc.json</code></strong>, <strong><code>ai setup</code></strong>, and <strong><code>ai generate --module</code></strong> for DDD layouts (<a href="/banana-universe/guide/philosophy.html">Philosophy</a>, <a href="/banana-universe/tooling/ai-module-generation.html">AI module generation</a>).</p><p>Package: <strong><code>@banana-universe/bananajs-cli</code></strong> · Binaries: <strong><code>bjs</code></strong> (shortcut), <strong><code>bananajs</code></strong>. Source: <strong><code>packages/bananajs-cli/src/index.ts</code></strong> (Commander.js).</p><h2 id="global" tabindex="-1">Global <a class="header-anchor" href="#global" aria-label="Permalink to &quot;Global&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --help</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><h2 id="bjs-new-appname" tabindex="-1"><code>bjs new [appName]</code> <a class="header-anchor" href="#bjs-new-appname" aria-label="Permalink to &quot;`bjs new [appName]`&quot;">​</a></h2><p>Scaffolds an app from <strong>built-in presets</strong> (MongoDB/Mongoose or SQL/TypeORM). Writes files under <strong><code>./&lt;appName&gt;</code></strong>—<strong>no git</strong> and no remote template.</p><ul><li>Prompts for app name if omitted (default suggestion: <strong><code>my-bananajs-app</code></strong>)</li><li>Interactive terminal: prompts for <strong>MongoDB</strong> vs <strong>SQL</strong> preset, then <strong>Flat</strong> vs <strong>DDD layered</strong> folder structure (default: <strong>flat</strong>)</li><li><strong><code>--preset &lt;id&gt;</code></strong> — <strong><code>mongodb</code></strong> | <strong><code>sql</code></strong> — skip the preset prompt (use in CI/scripts)</li><li>Non-interactive stdin (no TTY): defaults to <strong><code>sql</code></strong> preset and <strong>flat</strong> structure; pass <strong><code>--preset</code></strong> explicitly to choose MongoDB</li></ul><p><strong>Scaffold defaults</strong> (both presets):</p><ul><li><strong>Swagger</strong> — <strong><code>swagger.enabled: true</code></strong> in bootstrap; <strong><code>swagger-ui-express</code></strong> in <strong><code>dependencies</code></strong> so <strong><code>/api-docs</code></strong> works; OpenAPI JSON at <strong><code>/api-docs.json</code></strong>.</li><li><strong>Lint / format</strong> — ESLint 9 flat config + Prettier (<strong>tab width 4</strong>), <strong><code>.editorconfig</code></strong>, <strong><code>npm run lint</code></strong> / <strong><code>npm run format</code></strong>.</li><li><strong>DB</strong> — Connection/options live in <strong><code>src/db/</code></strong> (<strong><code>mongo.ts</code></strong> or <strong><code>typeorm-options.ts</code></strong>) with explicit error handling or validation; <strong><code>main.ts</code></strong> wraps startup in <strong><code>try/catch</code></strong>.</li><li><strong>Types</strong> — <strong><code>@types/node</code></strong>, <strong><code>@types/express</code></strong>, <strong><code>@types/swagger-ui-express</code></strong> as dev dependencies.</li><li><strong>Timestamps</strong> — Mongoose <strong><code>timestamps: true</code></strong> on sample schemas; TypeORM <strong><code>@CreateDateColumn</code></strong> / <strong><code>@UpdateDateColumn</code></strong> on sample entities where shown.</li></ul><p>Details: <a href="/banana-universe/guide/getting-started.html">Getting started</a> (section <strong>What the generated app includes</strong>).</p><h2 id="bjs-generate-type-name-alias-g" tabindex="-1"><code>bjs generate [type] [name]</code> (alias: <code>g</code>) <a class="header-anchor" href="#bjs-generate-type-name-alias-g" aria-label="Permalink to &quot;`bjs generate [type] [name]` (alias: `g`)&quot;">​</a></h2><p><strong>Types:</strong> <code>controller</code> | <code>dto</code> | <code>middleware</code> | <strong><code>module</code></strong></p><ul><li>Omit <strong><code>type</code></strong> and <strong><code>name</code></strong> in a <strong>TTY</strong> to be prompted (resource kind, then name).</li><li><strong><code>controller</code> / <code>dto</code> / <code>middleware</code></strong> — writes <strong><code>cwd/&lt;name&gt;.controller.ts</code></strong> (or <code>.dto.ts</code> / <code>.middleware.ts</code>).</li><li><strong><code>module</code></strong> — feature layout aligned with <strong><code>bjs new</code></strong>: <strong><code>src/modules/&lt;kebab&gt;/</code></strong> with <strong><code>createModule</code></strong> in <strong><code>index.ts</code></strong> and tsyringe <strong><code>@injectable</code> / <code>@inject</code></strong>. Two structure modes (prompted interactively; default: <strong>flat</strong>): <ul><li><strong>Flat</strong> <em>(default)</em> — controller, service, repository (interface + ORM impl), and DTO all at the module root; no subdirectories.</li><li><strong>DDD layered</strong> — <strong><code>domain/</code></strong> (entity + repository token), <strong><code>application/</code></strong>, <strong><code>infrastructure/</code></strong>, <strong><code>&lt;Pascal&gt;.dto.ts</code></strong> and <strong><code>&lt;Pascal&gt;.controller.ts</code></strong> at the module root.</li><li>After a successful write (not <strong><code>--dry-run</code></strong>), the CLI <strong>registers</strong> the module in <strong><code>bootstrap.ts</code></strong> and, for TypeORM, appends the ORM entity to <strong><code>entities[]</code></strong>.</li><li><strong><code>--structure ddd|flat</code></strong> — override the default (<strong><code>flat</code></strong>); omit to be prompted in a TTY.</li><li><strong><code>--orm typeorm|mongoose|none</code></strong> — infrastructure adapter (default: <strong><code>typeorm</code></strong> when non-interactive). <strong><code>--orm</code></strong> wins over <strong><code>--preset</code></strong>.</li><li><strong><code>--preset mongodb|sql</code></strong> — default ORM mapping.</li><li><strong><code>--out &lt;dir&gt;</code></strong> — base directory (default <strong><code>./src</code></strong>).</li><li><strong><code>--skip-bootstrap</code></strong> — do not patch <strong><code>bootstrap.ts</code></strong> or TypeORM <strong><code>entities[]</code></strong>.</li></ul></li><li><strong><code>--dry-run</code></strong> — print content without writing.</li></ul><p>See <a href="/banana-universe/guide/layered-architecture.html">Layered architecture &amp; DDD</a>.</p><h2 id="bjs-routes" tabindex="-1"><code>bjs routes</code> <a class="header-anchor" href="#bjs-routes" aria-label="Permalink to &quot;`bjs routes`&quot;">​</a></h2><p>Static scan for <code>@Controller</code> and HTTP decorators — prints a colored route table. <strong><code>--root &lt;dir&gt;</code></strong> sets the tree to scan (default <strong><code>src</code></strong>). In a <strong>TTY</strong> without <strong><code>--root</code></strong>, you are prompted for the directory.</p><h2 id="bjs-migrate" tabindex="-1"><code>bjs migrate</code> <a class="header-anchor" href="#bjs-migrate" aria-label="Permalink to &quot;`bjs migrate`&quot;">​</a></h2><p><strong>Express → BananaJS</strong> codemod. In a <strong>TTY</strong>, confirms before running.</p><h2 id="bjs-db" tabindex="-1"><code>bjs db</code> <a class="header-anchor" href="#bjs-db" aria-label="Permalink to &quot;`bjs db`&quot;">​</a></h2><ul><li><strong><code>--status</code></strong> — runs <strong><code>typeorm migration:show</code></strong> when a TypeORM config is present; if <strong><code>mongoose</code></strong> is in <code>package.json</code>, prints a short note (no migrate CLI).</li><li>With <strong>no flags</strong> in a <strong>TTY</strong>, choose an action from a short menu.</li></ul><h2 id="bjs-openapi-export" tabindex="-1"><code>bjs openapi export</code> <a class="header-anchor" href="#bjs-openapi-export" aria-label="Permalink to &quot;`bjs openapi export`&quot;">​</a></h2><ul><li><strong><code>--out &lt;path&gt;</code></strong> — OpenAPI spec output (default <strong><code>./openapi.json</code></strong> when unspecified).</li><li><strong><code>--client typescript</code></strong> — optional client generation (<code>openapi-typescript</code>).</li><li>In a <strong>TTY</strong>, you may be prompted for output path and whether to generate TypeScript types.</li></ul><h2 id="bjs-ai" tabindex="-1"><code>bjs ai</code> <a class="header-anchor" href="#bjs-ai" aria-label="Permalink to &quot;`bjs ai`&quot;">​</a></h2><p>Subcommands have <strong>one-letter aliases</strong> (e.g. <strong><code>bjs ai g</code></strong> = <strong><code>bjs ai generate</code></strong>). Full table: <strong><a href="/banana-universe/ai/">AI hub</a></strong>.</p><table tabindex="0"><thead><tr><th>Command</th><th>Alias</th><th>Purpose</th></tr></thead><tbody><tr><td><strong><code>ai setup</code></strong></td><td><strong><code>s</code></strong></td><td>Configure provider + <strong><code>.bananarc.json</code></strong></td></tr><tr><td><strong><code>ai generate</code></strong></td><td><strong><code>g</code></strong></td><td>Flat module scaffold <em>(default)</em> or DDD <strong><code>--module</code></strong> (LLM extraction); <strong>TTY</strong> walks through flat-module → DDD → legacy flat, then schema vs text. After write, registers bootstrap / TypeORM <strong><code>entities[]</code></strong> when applicable—same as <strong><code>bjs generate module</code></strong>.</td></tr><tr><td><strong><code>ai doc</code></strong></td><td><strong><code>d</code></strong></td><td>JSDoc on controllers; <strong><code>--file</code></strong>, <strong><code>--dry-run</code></strong></td></tr><tr><td><strong><code>ai review</code></strong></td><td><strong><code>r</code></strong></td><td>Structured LLM review; <strong><code>--file</code></strong>, <strong><code>--module</code></strong>, or positional path; <strong><code>--format json</code></strong>, <strong><code>--sarif</code></strong></td></tr><tr><td><strong><code>ai wire</code></strong></td><td><strong><code>w</code></strong></td><td>Bootstrap wiring hints (dry-run); optional <strong><code>--llm</code></strong></td></tr><tr><td><strong><code>ai test</code></strong></td><td><strong><code>t</code></strong></td><td>Scaffold <strong><code>node:test</code> + supertest</strong></td></tr><tr><td><strong><code>ai explain</code></strong></td><td><strong><code>e</code></strong></td><td>Short file summary</td></tr></tbody></table><p>Shared: <strong><code>--out &lt;dir&gt;</code></strong>, <strong><code>--dry-run</code></strong> where applicable.</p><div class="info custom-block"><p class="custom-block-title">Flat and DDD modules</p><p>Both <strong><code>bjs generate module</code></strong> and <strong><code>bjs ai generate</code></strong> support two folder structures — <strong>flat</strong> (default) and <strong>DDD layered</strong>:</p><ul><li><strong>Flat</strong> <em>(default)</em> — controller, service, repository, and DTO live at <strong><code>src/modules/&lt;feature&gt;/</code></strong> root; no <code>domain/</code> / <code>application/</code> / <code>infrastructure/</code> subdirs.</li><li><strong>DDD layered</strong> — full <strong><code>domain/</code></strong>, <strong><code>application/</code></strong>, <strong><code>infrastructure/</code></strong> subdirectory layout with DDD <code>Entity&lt;Props&gt;</code> base class and repository port pattern.</li></ul><p>Pass <strong><code>--structure flat</code></strong> (default) or <strong><code>--structure ddd</code></strong> to skip the interactive prompt. In a TTY, the prompt shows <strong>Flat</strong> first.</p><p><strong><code>bjs ai generate --module</code></strong> accepts <strong><code>--orm</code></strong> and <strong><code>--preset mongodb|sql</code></strong>. In <strong><code>.bananarc.json</code></strong>, <strong><code>generate.preset</code></strong> sets the default ORM when <strong><code>generate.defaultOrm</code></strong> is omitted (<strong><code>mongodb</code></strong> → mongoose, <strong><code>sql</code></strong> → typeorm).</p></div><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/banana-universe/tooling/ai-commands.html">AI commands</a></li><li><a href="/banana-universe/tooling/ai-module-generation.html">AI module generation</a></li><li><a href="/banana-universe/tooling/benchmarks.html">Benchmarks</a></li></ul>',30)])])}const h=e(n,[["render",d]]);export{u as __pageData,h as default};
